function featureStageStatus(feature:any){const complete=feature.stage==='VERIFIED',stage=feature.stage==='VERIFIED'?'VERIFICATION':feature.stage;return {label:`${workspaceStageLabels[stage]??stage} · ${complete?'已完成':'進行中'}`,kind:complete?'complete':'current'};}
function normalizePath(path:string){const url=new URL(path,location.origin);if(url.pathname==='/'||url.pathname==='/projects'||url.pathname==='/projects/'||url.pathname==='/terminal')url.pathname='/requirements';return url.pathname+url.search;}
function tabLabel(path:string){const url=new URL(path,location.origin),parts=url.pathname.split('/').filter(Boolean);if(parts[0]==='llm-settings')return 'LLM 設定';if(parts[0]==='workflow-settings')return '流程設定';if(parts[0]==='browser-recorder')return parts[1]?String(browserRecordings.value.find(item=>item.id===parts[1])?.fileName??'瀏覽器錄製').replace(/\.spec\.ts$/,''):'瀏覽器錄製';if(parts[0]==='requirements'&&parts[1]){const r=requirements.value.find(item=>item.id===parts[1]);if(!r)return '需求';const query=new URLSearchParams(url.search),feature=r.features.find((item:any)=>item.id===query.get('featureId')),stageKey=query.get('workflowStage')??'GHERKIN';return `${r.requirementKey} · ${workspaceStageLabels[stageKey]??'需求'}${feature?` · ${feature.featureKey}`:''}`;}if(parts[0]==='projects'&&parts[1]){const p=projects.value.find(item=>item.id===parts[1]);const section=({db:'資料庫',browser:'瀏覽器',terminal:'Terminal',recordings:'錄製腳本',integrations:'整合測試',runs:'執行報告'} as Record<string,string>)[parts[2]],label=parts[2]==='terminal'&&new URLSearchParams(url.search).get('kind')==='llm'?'LLM CLI':section;return `${p?.name??'專案'}${label?` · ${label}`:''}`;}return '需求清單';}
