function showTab(path:string,pushHistory=true){const normalized=normalizePath(path);if(!workspaceTabs.value.some(tab=>tab.path===normalized))workspaceTabs.value.push({path:normalized});activeTabPath.value=normalized;if(pushHistory)history.pushState({},'',normalized);else history.replaceState({},'',normalized);route.value=new URL(normalized,location.origin).pathname;routeLocation.value=normalized;void loadRoute();window.scrollTo({top:0,behavior:'instant'});}
