async function handleTerminalSessionStarted(event:{key:string;id:string}){if(workspaceTabs.value.some(tab=>tab.path===event.key)){terminalSessions[event.key]=event.id;return;}try{await api(`/terminals/${encodeURIComponent(event.id)}`,undefined,'DELETE');}catch(e){error.value=errorText(e);}}
