async function closeTab(tab:WorkspaceTab){const sessionId=terminalSessions[tab.path];if(sessionId){try{await api(`/terminals/${encodeURIComponent(sessionId)}`,undefined,'DELETE');delete terminalSessions[tab.path];}catch(e){error.value=errorText(e);return;}}const browserSession=browserRecorderDrafts[tab.path]?.sessionId;if(browserSession){try{await api(`/browser-sessions/${encodeURIComponent(browserSession)}`,undefined,'DELETE');}catch(e){error.value=errorText(e);return;}}delete pendingSavedBrowserReplays[tab.path];delete browserRecorderDrafts[tab.path];const index=workspaceTabs.value.findIndex(item=>item.path===tab.path);if(index<0)return;workspaceTabs.value.splice(index,1);if(activeTabPath.value!==tab.path)return;const next=workspaceTabs.value[Math.min(index,workspaceTabs.value.length-1)];if(next)showTab(next.path);else{workspaceTabs.value.push({path:'/requirements'});showTab('/requirements');}}
function popstate(){showTab(location.pathname+location.search,false);}
