async function action(name:string,fn:()=>Promise<any>){if(busy.value)return;busy.value=name;error.value='';try{return await fn();}catch(e){error.value=errorText(e);}finally{busy.value='';}}
async function loadProjects(){projects.value=items(await api('/projects'));}
async function loadBrowserRecordings(){browserRecordings.value=items(await api('/browser-recordings'));}
async function loadWorkflowSettings(){const result=await api('/workflow-settings');workflowAgents.value=result.agents??[];workflowAssignments.value=result.stages??[];}
function agentsForStage(stageKey:string){const assigned=new Set(workflowAssignments.value.find((item:any)=>item.key===stageKey)?.agentIds??[]);return workflowAgents.value.filter(agent=>assigned.has(agent.id));}
function editableStage(stageKey:string){return stage.value===stageKey&&visibleWorkflowStage.value===stageKey;}
function restartableStage(stageKey:string){const current=workflowStageOrder.findIndex(item=>item===stage.value),target=workflowStageOrder.findIndex(item=>item===stageKey);return target>=0&&current>target;}
async function loadRequirement(){if(!requirementId.value)return;const result=await api(`/requirements/${encodeURIComponent(requirementId.value)}${featureQuery()}`);requirement.value=result;const listed=requirements.value.find(r=>r.id===result.id);if(listed)Object.assign(listed,{features:result.features,projects:result.projects});linkedProjectIds.value=result.projects.map((p:any)=>p.id);if(!linkedProjectIds.value.includes(selectedProject.value))selectedProject.value=result.projectId??'';for(const kind of ['gherkin','sd','spec'])drafts[kind]=result.documents?.[kind]?.rawText??'';for(const p of result.sourceBaseline?.projects??[])sourceRefs[p.projectId]=p.sourceRef;pinnedSource.value=result.sourceBaseline?.projects?.find((p:any)=>p.projectId===projectId.value)?.resolvedCommit??result.sourceBaseline?.sourceRef??'';await loadScenarios();}
async function loadScenarios(){if(!requirementId.value)return;scenarioData.value=await api(`/requirements/${encodeURIComponent(requirementId.value)}/scenario-tests${featureQuery()}${activeRun.value?'&runId='+encodeURIComponent(activeRun.value):''}`);}
async function loadRoute(){
 const generation=++routeGeneration;loading.value=true;error.value='';sourcePath.value='';sourceText.value='';for(const key of Object.keys(sourceRefs))delete sourceRefs[key];questions.value=[];contexts.value='';selectedCases.value=[];recordingScript.value='';recordingActions.value=[];recordingState.value='idle';recordingExecutionConfig.value={};recordingSecretBindings.value='[]';browserUrl.value='';clearInterval(reportTimer);events?.close();activeRun.value='';pinnedSource.value='';sourceRef.value='';report.value=undefined;requirement.value=undefined;recording.value=undefined;browserId.value='';dbResult.value=undefined;schema.value=undefined;
 try{
   await Promise.all([loadProjects(),api('/requirements').then(result=>requirements.value=items(result)),loadBrowserRecordings(),loadWorkflowSettings()]);
  if(generation!==routeGeneration)return;
  if(requirementId.value){
   const listed=requirements.value.find(r=>r.id===requirementId.value);
   selectedFeature.value=new URLSearchParams(location.search).get('featureId')??listed?.features?.[0]?.id??'';
   await loadRequirement();connectEvents();
   if(projectId.value)await loadSource();
  }else if(projectId.value){
   const p=encodeURIComponent(projectId.value);connectEvents();
   if(view.value==='db'){connections.value=items(await api(`/projects/${p}/db-connections`));dbConnectionId.value=match.value[3]??connections.value[0]?.id??'';if(dbConnectionId.value)await refreshSchema();}
   else if(view.value==='browser')browserId.value=match.value[3]??'';
   else if(view.value==='recordings'||view.value==='integrations'){recordingPurpose.value=view.value==='integrations'?'integration':'recording';if(match.value[3])await loadRecording(match.value[3]);else recordings.value=items(await api(`/projects/${p}/recordings`));}
   else if(view.value==='runs'&&match.value[3]){activeRun.value=match.value[3];await loadReport();startReportPolling();}
  }else if(view.value==='browser-recorder'){
   const path=activeTabPath.value||routeLocation.value,draft=browserRecorderDraft(path),id=browserRecordingId.value;
   if(id&&draft.loadedRecordingId!==id){const saved=await api(`/recordings/${encodeURIComponent(id)}`);if(generation!==routeGeneration)return;if(saved.purpose!=='recording'||saved.projectId)throw Error('這份錄製不是全域瀏覽器錄製');draft.url=String(saved.executionConfig?.targetUrl??'');draft.script=String(saved.rawText??'');draft.actions=Array.isArray(saved.actions)?saved.actions:[];draft.state='stopped';draft.loadedRecordingId=id;}
  }
 }catch(e){if(generation===routeGeneration)error.value=errorText(e);}finally{if(generation===routeGeneration)loading.value=false;}
