async function loadSource(){if(!projectId.value)return;const source=await api(`/requirements/${encodeURIComponent(requirementId.value)}/source${featureQuery()}&projectId=${encodeURIComponent(projectId.value)}${sourcePath.value?'&path='+encodeURIComponent(sourcePath.value):''}`);sourceText.value=source.rawText;sourcePath.value=source.path;}
async function switchProject(){pinnedSource.value=requirement.value?.sourceBaseline?.projects?.find((p:any)=>p.projectId===projectId.value)?.resolvedCommit??'';sourcePath.value='';await action('source-load',loadSource);}
async function saveLinkedProjects(){await action('link-projects',async()=>{await api(`/requirements/${requirementId.value}/projects`,{projectIds:linkedProjectIds.value},'PUT');await loadRequirement();requirements.value=items(await api('/requirements'));notify('已更新相關專案；涉及的設計與下游基線需重新確認');});}
async function startWorkflowAgent(stageKey:string,agent:any){
 if(stageKey==='SD'){await workflow('generate-sd',agent.id);return;}
 if(stageKey==='TESTS'){await workflow('complete-tests',agent.id);return;}
 await action(`workflow-agent-${stageKey}`,async()=>{
  if(!projectId.value)throw Error('請先選擇需求所屬工作區。');
  const g=docs.value.gherkin;
  if(stageKey==='GHERKIN'&&(!g?.versionId||drafts.gherkin!==g.rawText))throw Error('請先保存目前的 Gherkin，再啟動 Agent。');
  const session=await api(`/requirements/${encodeURIComponent(requirementId.value)}/agent-sessions`,{stage:stageKey,agentId:agent.id,featureId:selectedFeature.value,projectId:projectId.value,...(stageKey==='GHERKIN'?{gherkinVersionId:g.versionId,gherkinSha256:g.rawSha256}:{})});
  const path=normalizePath(`/projects/${encodeURIComponent(projectId.value)}/terminal?kind=llm&session=${encodeURIComponent(session.id)}`);terminalSessions[path]=session.id;showTab(path);
 });
}

function connectEvents(){events=new WebSocket(socketUrl(requirementId.value?`/events?requirementId=${encodeURIComponent(requirementId.value)}`:`/events?projectId=${encodeURIComponent(projectId.value)}`));events.binaryType='arraybuffer';events.onmessage=async message=>{if(typeof message.data!=='string'){if(eventHeader){const h=eventHeader;eventHeader=undefined;await nextTick();runViewer.value?.present(h,message.data);}return;}let event:any;try{event=JSON.parse(message.data);}catch{return;}if(event.type==='browser.frame'){eventHeader=event;return;}if(event.requirementId&&requirementId.value&&event.requirementId!==requirementId.value)return;if(requirementId.value&&event.featureId&&event.featureId!==selectedFeature.value)return;if(view.value==='runs'&&event.runId&&event.runId!==activeRun.value)return;if(event.type==='llm.terminalOpened'){openLlmTerminal(event.projectId,event.terminalId);notify('已開啟 LLM CLI，可在網頁終端操作或中止');return;}if(event.type==='run.testStarted'||event.type==='run.browserBound'){activeRun.value=event.runId;await nextTick();if(event.type==='run.browserBound')runViewer.value?.bind(event);else runViewer.value?.started();startReportPolling();if(event.type==='run.testStarted'&&requirementId.value)await loadRequirement();}if(event.type==='run.completed'){activeRun.value=event.runId;await loadReport();runViewer.value?.ended();if(requirementId.value){await loadRequirement();}}};events.onerror=()=>{error.value='專案事件連線中斷，請重新整理以恢復即時狀態。';};}
async function createProject(){await action('create-project',async()=>{await api('/projects',newProject);dialog.value?.close();await loadProjects();if(!requirementId.value)navigate('/requirements');});}
function editProject(item:any){editingProjectId.value=item.id;projectDraft.name=item.name;projectDraft.workspaceRef=item.workspaceRef;}
function cancelEditProject(){editingProjectId.value='';projectDraft.name='';projectDraft.workspaceRef='';}
async function saveProject(id:string){await action('update-project',async()=>{await api(`/projects/${encodeURIComponent(id)}`,{name:projectDraft.name,workspaceRef:projectDraft.workspaceRef},'PUT');await loadProjects();if(projectId.value===id)await loadRoute();cancelEditProject();notify('工作區已更新');});}
async function createRequirement(){await action('create-requirement',async()=>{const result=await api('/requirements',{requirementKey:newRequirement.value,projectIds:newRequirementProjectIds.value});dialog.value?.close();newRequirementProjectIds.value=[];await loadProjects();await loadRoute();navigate(`/requirements/${result.id}`);});}
function startRenameRequirement(item:any){editingRequirementId.value=item.id;renamedRequirement.value=item.requirementKey;editingRequirementProjectIds.value=item.projects.map((project:any)=>project.id);}
