function cancelRenameRequirement(){editingRequirementId.value='';renamedRequirement.value='';editingRequirementProjectIds.value=[];}
function editingRequirementWorkspaceLabel(){return projects.value.filter((project:any)=>editingRequirementProjectIds.value.includes(project.id)).map((project:any)=>project.name).join('、')||'選擇工作區';}
function toggleRequirementExpansion(id:string){expandedRequirementId.value=expandedRequirementId.value===id?'':id;}
function startRenameFeature(feature:any){editingFeatureId.value=feature.id;renamedFeature.value=feature.featureKey;}
function cancelRenameFeature(){editingFeatureId.value='';renamedFeature.value='';}
async function renameFeature(requirement:string,feature:string){await action('rename-feature',async()=>{await api(`/requirements/${encodeURIComponent(requirement)}/features/${encodeURIComponent(feature)}`,{featureKey:renamedFeature.value},'PUT');await loadRoute();editingFeatureId.value='';renamedFeature.value='';notify('Gherkin 名稱已更新');});}
async function removeExample(r:any){if(!window.confirm(`刪除預設範例「${r.requirementKey}」？範例會從清單移除，既有執行證據會保留。`))return;await action('delete-example',async()=>{await api(`/requirements/${encodeURIComponent(r.id)}`,undefined,'DELETE');await loadRoute();notify('預設範例已刪除；既有執行證據保留');});}
function startCreateFeature(id:string){newFeatureRequirementId.value=id;openDialog('feature');}
async function createFeature(){await action('create-feature',async()=>{const id=newFeatureRequirementId.value||requirementId.value;const result=await api(`/requirements/${encodeURIComponent(id)}/features`,{featureKey:newFeature.value});dialog.value?.close();newFeatureRequirementId.value='';showTab(`/requirements/${encodeURIComponent(id)}?featureId=${encodeURIComponent(result.featureId)}&workflowStage=GHERKIN`);});}
function openDialog(kind:string){dialogKind.value=kind;candidateError.value='';if(kind==='requirement')newRequirementProjectIds.value=projectId.value? [projectId.value]:[];if(kind==='browser-recording-name'){const draft=browserRecorderDraft();browserRecordingName.value=browserRecordingId.value?String(browserRecordings.value.find(item=>item.id===browserRecordingId.value)?.fileName??'').replace(/\.spec\.ts$/,''):'瀏覽器錄製';}dialog.value?.showModal();}
function editable(kind:string){return stage.value===({gherkin:'GHERKIN',sd:'SD',spec:'TESTS'} as Record<string,string>)[kind];}
async function documentPayload(kind:string,text:string){const doc=docs.value[kind];return{rawText:text,baseVersionId:doc?.versionId,sourceGherkinVersionId:kind==='gherkin'?null:docs.value.gherkin?.versionId};}
async function saveDocument(kind:string){await action('save-'+kind,async()=>{const doc=docs.value[kind];if(!doc?.id)throw Error('文件尚未建立');await api(`/documents/${encodeURIComponent(doc.id)}/versions`,await documentPayload(kind,drafts[kind]));await loadRequirement();notify('已保存完整原文與新版本');});}
async function saveCandidate(){candidateError.value='';const doc=docs.value[candidateKind.value];if(!doc?.id){candidateError.value='文件尚未建立';return;}try{await api(`/documents/${encodeURIComponent(doc.id)}/versions`,await documentPayload(candidateKind.value,candidateText.value));await loadRequirement();dialog.value?.close();notify('候選已保存為新版本');}catch(e){candidateError.value=errorText(e);}}
async function confirm(kind:string){await action('confirm-'+kind,async()=>{const doc=docs.value[kind];try{await api(`/requirements/${requirementId.value}/confirm-${kind}`,{featureId:selectedFeature.value,versionId:doc.versionId,rawSha256:doc.rawSha256});}catch(error){if(kind==='sd'){await loadRequirement();if(stage.value==='TESTS')showTab(`/requirements/${encodeURIComponent(requirementId.value)}${featureQuery()}&workflowStage=TESTS`);}throw error;}await loadRequirement();if(kind==='sd')showTab(`/requirements/${encodeURIComponent(requirementId.value)}${featureQuery()}&workflowStage=TESTS`);});}
async function workflow(operation:string,agentId?:string){await action(operation,async()=>{const g=docs.value.gherkin,s=docs.value.sd,t=docs.value.spec;let context:any={};if(contexts.value.trim()){try{context=JSON.parse(contexts.value);}catch{throw Error('設計與測試 context 必須為有效 JSON');}}const result=await api(`/requirements/${requirementId.value}/${operation}`,{featureId:selectedFeature.value,gherkinVersionId:g?.versionId,gherkinSha256:g?.rawSha256,sdVersionId:s?.versionId,sdSha256:s?.rawSha256,skeletonVersionId:t?.testStage==='SKELETON'?t.versionId:t?.sourceSkeletonVersionId,skeletonHash:t?.testStage==='SKELETON'?t?.rawSha256:t?.manifest?.sourceSkeletonSha256,skeletonSha256:t?.testStage==='SKELETON'?t?.rawSha256:t?.manifest?.sourceSkeletonSha256,context,...(agentId?{agentId}:{})});questions.value=result.questions??[];await loadRequirement();if(result.terminal?.terminalId)openLlmTerminal(result.terminal.projectId,result.terminal.terminalId);});}
async function confirmTestSteps(){await action('confirm-test-steps',async()=>{await api(`/requirements/${encodeURIComponent(requirementId.value)}/start-development`,{featureId:selectedFeature.value});await loadRequirement();showTab(`/requirements/${encodeURIComponent(requirementId.value)}${featureQuery()}&workflowStage=IMPLEMENTATION`);});}
const returnArtifact=ref('Gherkin');
async function returnStage(){await action('return',async()=>{await api(`/requirements/${requirementId.value}/return`,{featureId:selectedFeature.value,artifactKind:returnArtifact.value});await loadRequirement();report.value=undefined;notify('已退回對應階段；下游基線與結果依依賴失效');});}
async function restartWorkflowStage(){const stageKey=visibleWorkflowStage.value,label=workspaceStageLabels[stageKey]??stageKey;await action('restart-stage',async()=>{await api(`/requirements/${encodeURIComponent(requirementId.value)}/restart-stage`,{featureId:selectedFeature.value,stage:stageKey});clearInterval(reportTimer);activeRun.value='';report.value=undefined;scenarioData.value=undefined;selectedCases.value=[];questions.value=[];ciState.value='NOT_RUN';ciRun.value='';await loadRequirement();notify(`已重啟「${label}」；本階段與後續階段回到未確認，歷史版本與報告保留。`);});}
async function saveSource(){await action('source',async()=>{await api(`/requirements/${requirementId.value}/source`,{featureId:selectedFeature.value,projectId:projectId.value,path:sourcePath.value,rawText:sourceText.value});notify('已保存至專案目錄');});}
async function pinSource(){await action('pin',async()=>{await api(`/requirements/${requirementId.value}/pin-source`,{featureId:selectedFeature.value,projects:requirement.value.projects.map((p:any)=>({projectId:p.id,sourceRef:sourceRefs[p.id]}))});await loadRequirement();});}
async function verify(mode:string,ids=selectedCases.value){await action('verify',async()=>{const baseline=testBaseline.value;const result=await api(`/requirements/${requirementId.value}/verify`,{featureId:selectedFeature.value,projectId:projectId.value,testBaselineId:baseline?.id??baseline?.baselineId,hash:baseline?.sha256,testBaselineHash:baseline?.sha256,selection:{mode,sourceCaseIds:mode==='ALL_REQUIRED'?[]:ids}});activeRun.value=result.runId??result.id;await loadReport();await loadRequirement();startReportPolling();});}
function caseId(c:any){return c.sourceCaseId??c.id;}
function caseKey(c:any){return c.caseId??c.caseKey??c.case_key??c.id;}
function caseTests(c:any){return c.testKeys??c.testIds??c.tests?.map((t:any)=>t.testKey??t.id)??[];}
function caseStatus(c:any){const current=report.value?.sourceCases?.find((s:any)=>s.sourceCaseId===caseId(c)||s.caseId===caseKey(c));return current?.status??c.executionStatus??c.status??'NOT_RUN';}
function caseSelected(c:any){if(report.value)return Boolean(report.value.sourceCases?.find((s:any)=>s.sourceCaseId===caseId(c)||s.caseId===caseKey(c))?.selected);return selectedCases.value.includes(caseId(c));}
function startReportPolling(){clearInterval(reportTimer);reportTimer=window.setInterval(()=>loadReport().catch(e=>{error.value=errorText(e);}),1200);}
async function loadReport(){if(!activeRun.value)return;report.value=await api(`/runs/${encodeURIComponent(activeRun.value)}/report`);if(['PASSED','FAILED','INVALID','INCOMPLETE'].includes(report.value.status)){clearInterval(reportTimer);runViewer.value?.ended();}if(requirementId.value)await loadScenarios();}
async function targetGit(operation:string){await action(operation,async()=>{ciState.value='running';try{const result=await api(`/requirements/${requirementId.value}/${operation}`,{featureId:selectedFeature.value,projectId:projectId.value,versionId:docs.value.spec?.versionId});if(result.runId){ciRun.value=result.runId;activeRun.value=result.runId;await loadReport();startReportPolling();}ciState.value=operation==='run-target-ci'?'completed':'saved';await loadRequirement();}catch(e){ciState.value='error';throw e;}});}
async function openDbGate(){await action('dbgate',async()=>{const session=await api(`/db-connections/${dbConnectionId.value}/browser`,{});browserId.value=session.id;});}
async function refreshSchema(){if(dbConnectionId.value)schema.value=await api(`/db-connections/${encodeURIComponent(dbConnectionId.value)}/schema`);}
async function runSql(){sqlState.value='running';dbResult.value=undefined;await action('sql',async()=>{try{const params=JSON.parse(sqlParams.value);dbResult.value=await api(`/db-connections/${encodeURIComponent(dbConnectionId.value)}/query`,{sql:sql.value,params});sqlState.value='completed';await refreshSchema();}catch(e){sqlState.value='error';throw e;}});}
async function createConnection(){await action('connection',async()=>{const result=await api(`/projects/${projectId.value}/db-connections`,{...newConnection,dbgateUrl:newConnection.dbgateUrl||undefined,dbgateConnectionName:newConnection.dbgateConnectionName||undefined});dialog.value?.close();navigate(`/projects/${projectId.value}/db/${result.id}`);});}
async function createBrowser(){await action('browser',async()=>{const result=await api('/browser-sessions',{projectId:projectId.value,workspaceRef:project.value?.workspaceRef,targetUrl:browserUrl.value||undefined});browserId.value=result.id??result.sessionId;replaceActiveTab(`/projects/${projectId.value}/browser/${browserId.value}`);});}
async function goToBrowserRecorderPage(){const draft=browserRecorderDraft();await action('browser-recorder-go',async()=>{const targetUrl=draft.url.trim();if(!targetUrl)throw Error('請輸入要開啟的網址');if(draft.sessionId)await api(`/browser-sessions/${encodeURIComponent(draft.sessionId)}/input`,{type:'navigate',url:targetUrl});else{const result=await api('/browser-sessions',{targetUrl});draft.sessionId=result.id??result.sessionId;}});}
async function toggleBrowserRecorder(){const draft=browserRecorderDraft();if(!draft.sessionId)return;const operation=draft.state==='recording'?'stop':'start';await action(`browser-recording-${operation}`,async()=>{const result=await api(`/browser-sessions/${encodeURIComponent(draft.sessionId)}/recordings/${operation}`,{});if(operation==='start'){draft.actions=[];draft.script='';draft.state='recording';}else{draft.actions=result.actions??[];draft.script=result.rawText??'';draft.state='stopped';}});}
async function replayBrowserRecording(){const draft=browserRecorderDraft();if(!draft.sessionId||!draft.actions.length)return;await action('browser-recording-replay',async()=>{await api(`/browser-sessions/${encodeURIComponent(draft.sessionId)}/recordings/replay`,{actions:draft.actions});});}
async function playSavedBrowserRecording(){const recordingId=browserRecordingId.value,path=activeTabPath.value,draft=browserRecorderDraft(path);if(!recordingId||!draft.actions.length)return;await action('saved-browser-recording-open',async()=>{if(draft.sessionId){await api(`/browser-sessions/${encodeURIComponent(draft.sessionId)}`,undefined,'DELETE');draft.sessionId='';}const result=await api('/browser-sessions',{targetUrl:draft.url||undefined});const sessionId=String(result.id??result.sessionId??'');if(!sessionId)throw Error('瀏覽器會話未提供 session ID');pendingSavedBrowserReplays[path]=sessionId;draft.sessionId=sessionId;});}
async function handleSavedBrowserViewerConnected(sessionId:string){const path=Object.keys(pendingSavedBrowserReplays).find(key=>pendingSavedBrowserReplays[key]===sessionId);if(!path)return;delete pendingSavedBrowserReplays[path];const draft=browserRecorderDraft(path);if(draft.sessionId!==sessionId)return;await action('saved-browser-recording-replay',async()=>{await api(`/browser-sessions/${encodeURIComponent(sessionId)}/recordings/replay`,{actions:draft.actions});notify('已完成 Playwright 動作重播');});}
function handleSavedBrowserViewerError(message:string){const path=activeTabPath.value;if(pendingSavedBrowserReplays[path])delete pendingSavedBrowserReplays[path];error.value=message;}
async function deleteSavedBrowserRecording(){const recordingId=browserRecordingId.value;if(!recordingId||!window.confirm('確定刪除此已保存的瀏覽器錄製？'))return;const path=activeTabPath.value;await action('saved-browser-recording-delete',async()=>{const draft=browserRecorderDraft(path);if(draft.sessionId){await api(`/browser-sessions/${encodeURIComponent(draft.sessionId)}`,undefined,'DELETE');draft.sessionId='';}delete pendingSavedBrowserReplays[path];await api(`/browser-recordings/${encodeURIComponent(recordingId)}`,undefined,'DELETE');const tab=workspaceTabs.value.find(item=>item.path===path);if(tab)await closeTab(tab);else navigate('/browser-recorder');await loadBrowserRecordings();});}
function handleBrowserRecorderEvent(event:any){if(event.type==='browser.pageChanged'&&typeof event.payload?.url==='string')browserRecorderDraft().url=event.payload.url;}
async function saveBrowserRecording(){const draft=browserRecorderDraft();await action('browser-recording-save',async()=>{const name=browserRecordingName.value.trim();if(!name)throw Error('請輸入錄製名稱');const fileName=name.endsWith('.spec.ts')?name:`${name}.spec.ts`;await api('/recordings',{fileName,rawText:draft.script,actions:draft.actions,executionConfig:{targetUrl:draft.url}});dialog.value?.close();await loadBrowserRecordings();});}
async function closeBrowser(){await action('browser-close',async()=>{await api(`/browser-sessions/${browserId.value}`,undefined,'DELETE');browserId.value='';recordingState.value='idle';navigate(`/projects/${projectId.value}/browser`);});}
async function record(operation:string){await action('record-'+operation,async()=>{const result=await api(`/browser-sessions/${browserId.value}/recordings/${operation}`,{});recordingState.value=operation==='start'?'recording':'stopped';if(operation==='stop'){recordingActions.value=result.actions??[];recordingScript.value=result.rawText??result.script??'';}});}
async function addAssertion(){await action('assertion',async()=>{await api(`/browser-sessions/${browserId.value}/assertions`,{locator:recordLocator.value,assertionType:assertionType.value,expected:recordExpected.value});notify('已將明確斷言加入錄製');});}
async function saveRecording(){await action('recording-save',async()=>{const result=await api(recordingPurpose.value==='integration'?'/integration-tests':'/recordings',{projectId:projectId.value,requirementId:null,rawText:recordingScript.value,actions:recordingActions.value,sourceCases:[],executionConfig:savedRecordingConfig()});navigate(`/projects/${projectId.value}/recordings/${result.id}`);});}
async function createIntegration(){await action('integration-save',async()=>{const result=await api('/integration-tests',{projectId:projectId.value,rawText:integrationDraft.value,fileName:integrationFileName.value,executionConfig:{targetUrl:integrationTargetUrl.value}});dialog.value?.close();navigate(`/projects/${projectId.value}/recordings/${result.id}`);});}
async function loadRecording(id:string){const generation=routeGeneration,requestedProject=projectId.value;const result=await api(`/recordings/${id}`);if(generation!==routeGeneration||requestedProject!==projectId.value||(result.projectId&&result.projectId!==requestedProject))return;recording.value=result;recordingScript.value=result.rawText??result.head?.rawText??'';recordingActions.value=result.actions??result.head?.actions??[];recordingExecutionConfig.value={...(result.executionConfig??result.head?.executionConfig??{})};recordingSecretBindings.value=pretty(recordingExecutionConfig.value.secretBindings??[]);browserUrl.value=String(result.targetUrl??recordingExecutionConfig.value.targetUrl??'');recordingPurpose.value=result.purpose??'recording';}
async function saveRecordingRevision(){await action('recording-version',async()=>{await api(`/documents/${recording.value.id}/versions`,{rawText:recordingScript.value,actions:recordingActions.value,executionConfig:savedRecordingConfig()});await loadRecording(recording.value.id);notify('已另存新版本');});}
async function replay(){await action('replay',async()=>{const version=recording.value.versionId??recording.value.head?.versionId;const result=await api(`/scripts/${recording.value.id}/versions/${version}/replay`,{projectId:projectId.value,targetUrl:recording.value.executionConfig?.targetUrl??recording.value.head?.executionConfig?.targetUrl??browserUrl.value});activeRun.value=result.runId??result.id;await loadReport();startReportPolling();});}
onMounted(()=>{window.addEventListener('popstate',popstate);const initial=normalizePath(location.pathname+location.search);if(location.pathname+location.search!==initial)history.replaceState({},'',initial);route.value=new URL(initial,location.origin).pathname;workspaceTabs.value=[{path:initial}];activeTabPath.value=initial;routeLocation.value=initial;loadRoute();});
onBeforeUnmount(()=>{window.removeEventListener('popstate',popstate);events?.close();clearInterval(reportTimer);});
</script>

<template>
  <div class="workbench-shell requirement-shell">
    <RequirementSidebar :requirements="requirements" :projects="projects" :browser-recordings="browserRecordings" :browser-recording-id="browserRecordingId" :requirement-id="requirementId" :feature-id="selectedFeature" :workflow-stage="workflowStage" :view="view" @navigate="navigate" @create-requirement="openDialog('requirement')" @create-feature="startCreateFeature" />
    <div class="main-shell" :class="{'terminal-shell':view==='terminal','browser-recorder-shell':view==='browser-recorder'}">
      <nav class="workspace-tabs" data-testid="workspace-tabs" aria-label="工作頁籤"><div v-for="tab in workspaceTabs" :key="tab.path" class="workspace-tab" :class="{active:activeTabPath===tab.path}"><button class="workspace-tab-select" :aria-current="activeTabPath===tab.path?'page':undefined" :title="tabLabel(tab.path)" @click="selectTab(tab)">{{tabLabel(tab.path)}}</button><button class="workspace-tab-close" type="button" :aria-label="'關閉 '+tabLabel(tab.path)" :title="'關閉 '+tabLabel(tab.path)" @click="closeTab(tab)">×</button></div></nav>
      <main :class="{'terminal-main':view==='terminal','browser-recorder-main':view==='browser-recorder','full-screen-main':view==='requirements'&&['GHERKIN','SD','TESTS'].includes(visibleWorkflowStage)}">
        <div v-if="error&&view!=='terminal'" class="error-banner" role="alert"><div><strong>操作未完成</strong><pre>{{error}}</pre></div><button aria-label="關閉錯誤" @click="error=''">×</button></div>
        <div v-if="loading&&view!=='terminal'" class="loading-state"><span class="loading-spinner"></span>正在讀取工作區…</div>
        <template v-else-if="view==='llm-settings'"><LlmSettingsPage @saved="loadWorkflowSettings" /></template>
        <template v-else-if="view==='workflow-settings'"><WorkflowSettingsPage @saved="loadWorkflowSettings" /></template>
        <template v-else-if="view==='requirement-list'">
          <div class="page-header compact"><div><span class="eyebrow">REQUIREMENTS</span><h1>需求工作台</h1><p>從需求開始，確認設計、開發並驗證相關專案。</p></div><button class="button primary" @click="openDialog('requirement')">＋ 新增需求</button></div>
          <section class="panel"><div class="panel-heading"><h2>需求清單</h2><span>{{requirements.length}} 項需求</span></div><div class="requirement-list"><div v-for="r in requirements" :key="r.id" class="requirement-list-entry"><div class="requirement-row"><span class="document-symbol">▤</span><div class="requirement-row-content"><div class="requirement-name-row"><template v-if="editingRequirementId===r.id"><input v-model="renamedRequirement" class="requirement-name-edit" :aria-label="'需求名稱 '+r.requirementKey" required maxlength="160" autofocus @keydown.enter.prevent="renameRequirement(r.id)" @keydown.esc.prevent="cancelRenameRequirement"><details class="requirement-workspace-dropdown"><summary :aria-label="'選擇需求工作區 '+r.requirementKey">{{editingRequirementWorkspaceLabel()}}</summary><div class="requirement-workspace-options"><label v-for="project in projects" :key="project.id"><input v-model="editingRequirementProjectIds" type="checkbox" :value="project.id"><span>{{project.name}}</span></label><p v-if="!projects.length">尚無可選工作區</p></div></details></template><button v-else type="button" class="requirement-title-toggle" :aria-label="(expandedRequirementId===r.id?'收合需求 ':'展開需求 ')+r.requirementKey" :aria-expanded="expandedRequirementId===r.id" @click="toggleRequirementExpansion(r.id)"><strong>{{r.requirementKey}}</strong><span class="requirement-chevron">{{expandedRequirementId===r.id?'⌃':'⌄'}}</span></button><span v-if="r.isExample" class="tag">預設範例</span><button type="button" class="requirement-name-action" :aria-label="editingRequirementId===r.id?'保存需求名稱':'重新命名 '+r.requirementKey" :title="editingRequirementId===r.id?'保存名稱':'重新命名'" :disabled="!!busy" @click="editingRequirementId===r.id?renameRequirement(r.id):startRenameRequirement(r)">{{editingRequirementId===r.id?'✓':'✎'}}</button></div><div class="requirement-row-link"><p>{{r.projects.map((p:any)=>p.name).join('、')||'尚未關聯程式碼專案'}}</p><span class="tag">{{r.features.length}} 份 Gherkin</span></div></div><button v-if="r.isExample" data-testid="delete-default-example" class="button small" :disabled="!!busy" @click="removeExample(r)">刪除範例</button></div><div v-if="expandedRequirementId===r.id" class="requirement-children" :aria-label="r.requirementKey+' 的 Gherkin 名稱'"><div v-for="feature in r.features" :key="feature.id" class="requirement-child-row"><span class="requirement-child-branch" aria-hidden="true">└</span><input v-if="editingFeatureId===feature.id" v-model="renamedFeature" class="requirement-feature-edit" :aria-label="'Gherkin 名稱 '+feature.featureKey" required maxlength="160" autofocus @keydown.enter.prevent="renameFeature(r.id,feature.id)" @keydown.esc.prevent="cancelRenameFeature"><span v-else class="requirement-child-name">{{feature.featureKey}}</span><span class="requirement-feature-status" :class="'is-'+featureStageStatus(feature).kind" :aria-label="featureStageStatus(feature).label" role="status"><span aria-hidden="true">{{featureStageStatus(feature).kind==='complete'?'✓':'●'}}</span>{{featureStageStatus(feature).label}}</span><button type="button" class="requirement-name-action" :aria-label="editingFeatureId===feature.id?'保存 Gherkin 名稱':'重新命名 Gherkin '+feature.featureKey" :title="editingFeatureId===feature.id?'保存名稱':'重新命名'" :disabled="!!busy" @click="editingFeatureId===feature.id?renameFeature(r.id,feature.id):startRenameFeature(feature)">{{editingFeatureId===feature.id?'✓':'✎'}}</button></div><span v-if="!r.features.length" class="requirement-child-empty">尚未建立 Gherkin</span></div></div></div><p v-if="!requirements.length" class="empty-small">建立需求後，選取 Gherkin 並點選左側階段。</p></section>
          <section class="panel workspace-home-panel"><div class="panel-heading"><h2>工作區管理</h2><button class="button small" @click="openDialog('project')">＋ 新增工作區</button></div><div class="workspace-list"><div v-for="p in projects" :key="p.id" class="workspace-list-entry"><a v-if="editingProjectId!==p.id" class="workspace-list-link" :href="`/projects/${p.id}`" @click.prevent="navigate(`/projects/${p.id}`)"><span class="document-symbol">▦</span><div><strong>{{p.name}}</strong><p class="mono">{{p.workspaceRef}}</p></div><span class="arrow-link">→</span></a><form v-else class="workspace-edit-form" @submit.prevent="saveProject(p.id)"><label>工作區名稱<input v-model="projectDraft.name" required maxlength="160" autofocus></label><label>本機程式碼目錄<input v-model="projectDraft.workspaceRef" required></label><button class="button primary small" :disabled="!!busy">保存</button><button type="button" class="button small" :disabled="!!busy" @click="cancelEditProject">取消</button></form><div v-if="editingProjectId!==p.id" class="workspace-list-actions"><button type="button" class="workspace-db-button" :data-testid="'workspace-database-'+p.id" @click="navigate(`/projects/${p.id}/db`)">資料庫</button><button type="button" class="workspace-edit-button" :aria-label="'編輯 '+p.name" title="編輯工作區" :disabled="!!busy" @click="editProject(p)">✎</button></div></div></div><p v-if="!projects.length" class="empty-small">尚未新增工作區。新增本機程式碼目錄後，建立需求時可選擇一個或多個工作區。</p></section>
        </template>
        <template v-else-if="view==='terminal'"><TerminalPane v-if="project" :key="project.id" :project-id="project.id" :workspace-ref="project.workspaceRef" :session-key="activeTabPath" :session-id="terminalSessions[activeTabPath]" :auto-open="true" @session-started="handleTerminalSessionStarted" /></template>
        <template v-else-if="view==='browser-recorder'">
          <section v-if="browserRecordingId" class="saved-browser-recording" :class="{playing:!!activeBrowserRecorderDraft.sessionId}">
            <div class="saved-browser-recording-actions">
              <button type="button" class="button primary" data-testid="play-saved-browser-recording" :disabled="!!busy||!!pendingSavedBrowserReplays[activeTabPath]||!activeBrowserRecorderDraft.actions.length" @click="playSavedBrowserRecording">{{busy==='saved-browser-recording-replay'?'播放中…':pendingSavedBrowserReplays[activeTabPath]?'瀏覽器連線中…':'播放'}}</button>
              <button type="button" class="button" data-testid="delete-saved-browser-recording" :disabled="!!busy" @click="deleteSavedBrowserRecording">刪除</button>
            </div>
            <div class="saved-browser-recording-viewer" v-show="activeBrowserRecorderDraft.sessionId"><BrowserViewer ref="globalBrowserViewer" :session-id="activeBrowserRecorderDraft.sessionId" interactive minimal @connected="handleSavedBrowserViewerConnected" @event="handleBrowserRecorderEvent" @error="handleSavedBrowserViewerError" /></div>
            <textarea data-testid="saved-browser-recording-script" class="code-editor saved-browser-recording-script" :value="activeBrowserRecorderDraft.script" readonly spellcheck="false" aria-label="Playwright 腳本"></textarea>
          </section>
          <section v-else class="global-browser-recorder"><form class="global-browser-toolbar" data-testid="global-browser-toolbar" @submit.prevent="goToBrowserRecorderPage"><input v-model="activeBrowserRecorderDraft.url" data-testid="global-browser-url" type="url" aria-label="瀏覽器網址" placeholder="https://…"><button class="button small" :disabled="!!busy">前往</button><button type="button" class="button small" :disabled="!activeBrowserRecorderDraft.sessionId||!!busy" @click="toggleBrowserRecorder">{{activeBrowserRecorderDraft.state==='recording'?'停止錄製':'錄製'}}</button><button type="button" class="button small" :disabled="!activeBrowserRecorderDraft.sessionId||!activeBrowserRecorderDraft.actions.length||activeBrowserRecorderDraft.state==='recording'||!!busy" @click="replayBrowserRecording">重播</button><button type="button" class="button small" :disabled="activeBrowserRecorderDraft.state!=='stopped'||!activeBrowserRecorderDraft.actions.length||!!busy" @click="openDialog('browser-recording-name')">保存</button></form><BrowserViewer ref="globalBrowserViewer" :session-id="activeBrowserRecorderDraft.sessionId" interactive minimal @event="handleBrowserRecorderEvent" @error="error=$event" /></section>
        </template>
        <template v-else-if="view==='overview'">
          <div class="page-header compact"><div><span class="eyebrow">LOCAL CODE PROJECT</span><h1>{{project?.name}}</h1><p class="mono">{{project?.workspaceRef}}</p></div></div>
          <section class="panel"><div class="panel-heading"><h2>專案工具</h2></div><div class="panel-body button-row"><button class="button" @click="navigate(`/projects/${projectId}/recordings`)">錄製腳本</button><button class="button" @click="navigate(`/projects/${projectId}/integrations`)">整合測試</button></div></section>
          <section class="panel"><div class="panel-heading"><h2>相關需求</h2></div><div class="requirement-list"><a v-for="r in requirements.filter(r=>r.projects.some((p:any)=>p.id===projectId))" :key="r.id" :href="`/requirements/${r.id}`" @click.prevent="navigate(`/requirements/${r.id}`)"><strong>{{r.requirementKey}}</strong><span class="tag">{{r.features.length}} 份 Gherkin</span></a></div></section>
        </template>
        <template v-else-if="view==='requirements'&&requirement">
          <section v-if="visibleWorkflowStage==='GHERKIN'&&requirement.projects.length>1" class="panel requirement-projects"><div class="panel-body"><div class="field"><label for="execution-project">目前工作區</label><select id="execution-project" data-testid="execution-project" v-model="selectedProject" @change="switchProject"><option v-for="p in requirement.projects" :key="p.id" :value="p.id">{{p.name}}</option></select></div></div></section>
                    <div class="requirement-layout" data-testid="workflow-stage-content" :data-stage="visibleWorkflowStage"><div class="document-column">
            <section v-for="kind in visibleArtifacts" :key="kind" class="panel document-panel" :class="{locked:!editable(kind)}"><div class="panel-heading"><div><span class="eyebrow">{{kind==='gherkin'?'ACCEPTANCE CRITERIA':kind==='sd'?'SYSTEM DESIGN':'TEST SPECIFICATION'}}</span><h2>{{artifactNames[kind]}} <span class="tag" v-if="!editable(kind)">唯讀</span></h2></div><span class="version-info">{{docs[kind]?.versionId?'v'+(docs[kind]?.version??docs[kind]?.versionNo??' · '+short(docs[kind]?.versionId)):'尚無已存版本'}}</span></div><div class="panel-body"><div v-if="kind==='sd'&&!sdConfirmed" class="document-mode-switch" role="group" aria-label="系統設計文件模式"><button type="button" :aria-pressed="sdMode==='edit'" :class="{active:sdMode==='edit'}" @click="sdMode='edit'">編輯</button><button type="button" :aria-pressed="sdMode==='preview'" :class="{active:sdMode==='preview'}" @click="sdMode='preview'">預覽</button></div><details v-if="kind==='sd'&&!sdConfirmed" class="generation-context"><summary>設計與測試 context（JSON）</summary><textarea v-model="contexts" class="code-editor short-editor" :readonly="stage!=='SD'" placeholder='{"targetUrl":"…","database":"…"}' aria-label="設計與測試 context"></textarea></details><div v-if="kind==='gherkin'&&editable(kind)" class="workflow-stage-agent-actions" data-testid="gherkin-agent-actions"><button v-for="agent in agentsForStage('GHERKIN')" :key="agent.id" type="button" class="button primary small" :data-testid="'start-agent-GHERKIN-'+agent.id" :disabled="!!busy||!docs.gherkin?.versionId||drafts.gherkin!==docs.gherkin?.rawText||!projectId" @click="startWorkflowAgent('GHERKIN',agent)">{{agent.name}} · 啟動 CLI</button></div><GherkinEditor v-if="kind==='gherkin'" v-model="drafts.gherkin" test-id="gherkin-editor" :readonly="!editable(kind)" label="Gherkin 原文" placeholder="在這裡撰寫 Gherkin 驗收條件…"/><div v-else-if="kind==='sd'" class="sd-document-editor"><DocumentEditor v-if="!sdConfirmed&&sdMode==='edit'" test-id="sd-editor" v-model="drafts.sd" :readonly="!editable(kind)" label="SD 原文" placeholder="SD 草稿將包含架構與資料庫 DDL / DML…"/><MarkdownPreview v-else :source="drafts.sd" /></div><div v-else-if="kind==='spec'" data-testid="spec-editor" class="generated-spec-summary"><p v-if="docs.spec?.versionId">已依確認的 Gherkin 與 SD 自動產生測試骨架；spec.ts 為唯讀檔案。</p><p v-else>確認 SD 後會自動產生測試骨架。</p></div><div v-if="!(kind==='sd'&&sdConfirmed)" class="hash-line"><span>SHA-256</span><code>{{docs[kind]?.rawSha256??'尚未保存'}}</code></div><div v-if="!(kind==='sd'&&sdConfirmed)" class="document-actions"><button v-if="kind!=='spec'" class="button small" :disabled="!editable(kind)||!!busy||!drafts[kind]" @click="saveDocument(kind)">保存新版本</button><button v-if="kind==='gherkin'" data-testid="confirm-gherkin" class="button primary small" :disabled="stage!=='GHERKIN'||!docs.gherkin?.versionId||!!busy||drafts.gherkin!==docs.gherkin?.rawText" @click="confirm('gherkin')">確認此 Gherkin</button><template v-if="kind==='sd'"><template v-if="editable(kind)"><button v-for="agent in agentsForStage('SD')" :key="agent.id" :data-testid="'generate-sd-'+agent.id" class="button small" :disabled="!!busy" @click="startWorkflowAgent('SD',agent)">產生 SD · {{agent.name}}</button></template><button data-testid="confirm-sd" class="button primary small" :disabled="stage!=='SD'||!docs.sd?.versionId||!!busy||drafts.sd!==docs.sd?.rawText" @click="confirm('sd')">確認此 SD</button></template><template v-if="kind==='spec'"><button v-if="!docs.spec?.versionId" data-testid="generate-tests" class="button small" :disabled="stage!=='TESTS'||!!busy" @click="workflow('generate-tests')">重新產生測試骨架</button><template v-if="docs.spec?.versionId&&testReadiness!=='COMPLETED'&&editable(kind)"><button v-for="agent in agentsForStage('TESTS')" :key="agent.id" :data-testid="'complete-tests-'+agent.id" class="button primary small" :disabled="!!busy" @click="startWorkflowAgent('TESTS',agent)">{{busy==='complete-tests'?'產生中…':'產生測試步驟 · '+agent.name}}</button></template><button v-if="testReadiness==='COMPLETED'" data-testid="confirm-test-steps" class="button primary small" :disabled="stage!=='TESTS'||!!busy" @click="confirmTestSteps">確認測試步驟</button></template></div>
              <template v-if="kind==='spec'"><details><summary>設計與測試 context（JSON）</summary><textarea v-model="contexts" class="code-editor short-editor" :readonly="!['SD','TESTS'].includes(stage)" placeholder='{"targetUrl":"…","expected":"…"}' aria-label="設計與測試 context"></textarea></details><div v-if="questions.length" data-testid="llm-needs-input" class="needs-input"><strong>需要補充資訊</strong><ul><li v-for="q in questions" :key="q">{{q}}</li></ul></div><details class="generated-detail"><summary>自動產生的 spec.ts、路徑與映射（點選展開）</summary><p data-testid="generated-spec-path" class="mono">{{docs.spec?.manifest?.specPath??docs.spec?.specPath??docs.spec?.fileName??'generated/'+requirement.requirementKey+'.spec.ts'}}</p><textarea data-testid="generated-spec-source" class="code-editor short-editor" readonly :value="docs.spec?.rawText??''" aria-label="已生成 spec 原文"></textarea><textarea data-testid="generated-manifest" class="code-editor short-editor" readonly :value="pretty(docs.spec?.manifest)" aria-label="生成 manifest"></textarea></details></template>
            </div></section>
            <section v-if="visibleWorkflowStage==='IMPLEMENTATION'" class="panel"><div class="panel-heading"><div><span class="eyebrow">IMPLEMENTATION</span><h2>產品程式與固定版本</h2></div></div><div class="panel-body"><div class="baseline-row"><span data-testid="confirmed-gherkin">Gherkin {{requirement.confirmations?.gherkin?'已確認':'尚未確認'}} {{short(requirement.confirmations?.gherkin?.versionId)}} / {{short(requirement.confirmations?.gherkin?.rawSha256)}}</span><span data-testid="confirmed-sd">SD {{requirement.confirmations?.sd?'已確認':'尚未確認'}} {{short(requirement.confirmations?.sd?.versionId)}} / {{short(requirement.confirmations?.sd?.rawSha256)}}</span><span data-testid="test-baseline">測試基線 {{short(testBaseline?.id)}}</span></div><div v-if="editableStage('IMPLEMENTATION')" class="workflow-stage-agent-actions" data-testid="implementation-agent-actions"><button v-for="agent in agentsForStage('IMPLEMENTATION')" :key="agent.id" type="button" class="button primary small" :data-testid="'start-agent-IMPLEMENTATION-'+agent.id" :disabled="!!busy||!projectId" @click="startWorkflowAgent('IMPLEMENTATION',agent)">{{agent.name}} · 啟動 CLI</button></div><div class="field"><label for="source-path">專案內檔案路徑</label><div class="button-row"><input id="source-path" v-model="sourcePath" placeholder="例如：src/main.ts" :disabled="!projectId"><button class="button small" :disabled="!projectId||!sourcePath||!!busy" @click="action('source-load',loadSource)">讀取檔案</button></div><small class="mono">{{project?.workspaceRef}}</small></div><textarea data-testid="source-editor" v-model="sourceText" class="code-editor" :readonly="stage!=='IMPLEMENTATION'" aria-label="產品程式編輯器" spellcheck="false" placeholder="在工作區編輯產品程式…"></textarea><div class="document-actions"><button class="button small" :disabled="stage!=='IMPLEMENTATION'||!sourcePath||!!busy" @click="saveSource">保存程式</button></div><div v-for="p in requirement.projects" :key="p.id" class="source-pin"><div class="field"><label :for="'source-'+p.id">{{p.name}} · Git 版本</label><input :id="'source-'+p.id" :data-testid="p.id===projectId?'source-ref':'project-source-'+p.id" v-model="sourceRefs[p.id]" class="mono" placeholder="Git commit / revision"><small class="mono">{{requirement.sourceBaseline?.projects?.find((s:any)=>s.projectId===p.id)?.resolvedCommit||'尚未固定版本'}}</small></div></div><button data-testid="pin-source" class="button" :disabled="!['IMPLEMENTATION','VERIFICATION','VERIFIED'].includes(stage)||!requirement.projects.length||requirement.projects.some((p:any)=>!sourceRefs[p.id]?.trim())||!!busy" @click="pinSource">固定全部專案版本</button><div class="hash-line"><span>PINNED</span><code data-testid="pinned-source-ref">{{pinnedSource}}</code></div></div></section>
            <section v-if="visibleWorkflowStage==='VERIFICATION'" data-testid="scenario-tests" class="panel"><div class="panel-heading"><div><span class="eyebrow">TRACEABLE TESTS</span><h2>情境與測試映射</h2></div><button class="button quiet small" @click="loadScenarios">↻ 更新</button></div><div v-if="scenarioCases.length" class="table-scroll"><table><thead><tr><th>選取</th><th>來源情境 / 案例</th><th>測試 ID</th><th>撰寫狀態</th><th>本次執行</th><th></th></tr></thead><tbody><tr v-for="c in scenarioCases" :key="caseId(c)" :data-testid="'scenario-case-'+caseKey(c)" :data-selected="String(caseSelected(c))"><td><input data-testid="case-select" v-model="selectedCases" type="checkbox" :value="caseId(c)" :disabled="!canVerify" aria-label="選取案例"></td><td><strong>{{c.scenarioId??c.scenarioKey}}</strong><p class="muted">{{caseKey(c)}} {{c.title??''}}</p></td><td data-testid="case-test-ids" class="mono">{{caseTests(c).join('\n')}}</td><td><span data-testid="case-readiness" class="tag">{{c.readiness??(testReadiness==='COMPLETED'?'COMPLETED':'PENDING_COMPLETION')}}</span></td><td><span data-testid="case-execution-status" class="tag" :class="{ready:caseStatus(c)==='PASSED',failed:caseStatus(c)==='FAILED'}">{{caseStatus(c)}}</span></td><td><button data-testid="case-run" class="button small" :disabled="!canVerify||!!busy" @click="verify('SELECTED_CASES',[caseId(c)])">執行</button></td></tr></tbody></table></div><p v-else class="empty-small">保存 Gherkin 並產生測試後，顯示真實來源案例與映射。</p><div class="panel-footer"><p>選取案例會執行其全部必要測試；局部通過不代表全案通過。</p><div class="button-row"><button data-testid="run-selected-cases" class="button" :disabled="!canVerify||!selectedCases.length||!!busy" @click="verify('SELECTED_CASES')">執行所選 {{selectedCases.length||''}}</button><button data-testid="run-verification" class="button primary" :disabled="!canVerify||!!busy" @click="verify('ALL_REQUIRED')">驗證全部必要測試</button></div></div></section>
            <section v-if="visibleWorkflowStage==='VERIFICATION'" class="panel"><div class="panel-heading"><div><span class="eyebrow">TARGET GIT / CI</span><h2>標準專案測試</h2></div><span class="tag">Git 為權威來源</span></div><div class="panel-body"><p class="muted">SQLite 保存指定版本副本；只有明確保存到 target Git 才變更專案檔案。CI 以其實際 tested commit 回報。</p><div class="document-actions"><button data-testid="save-to-target-git" class="button" :disabled="stage!=='TESTS'||!!busy" @click="targetGit('save-to-target-git')">保存至 target Git</button><button data-testid="run-target-ci" class="button" :disabled="!docs.spec?.versionId||!!busy" @click="targetGit('run-target-ci')">執行專案 CI</button><span data-testid="ci-state" class="tag">{{ciState}}</span><code data-testid="ci-run-id">{{ciRun}}</code></div></div></section>
          </div><aside v-if="visibleWorkflowStage==='VERIFICATION'" class="execution-column"><section class="panel sticky-viewer"><div class="panel-heading"><div><span class="eyebrow">LIVE EXECUTION</span><h2>目前執行畫面</h2></div><span class="tag">{{report?.status??'NOT_RUN'}}</span></div><BrowserViewer ref="runViewer" :project-id="projectId" :run-id="activeRun" @error="error=$event"/><div class="viewer-description"><span class="mono">{{activeRun||'尚無執行紀錄'}}</span><p>畫格依 run、test、session 與 page 綁定；不以 Trace 或另開網站替代。</p></div></section><section class="panel"><div class="panel-heading"><h2>退回修改</h2></div><div class="panel-body"><p class="muted small-text">修改上游前先退回。既有下游確認、測試與結果將依依賴失效。</p><select data-testid="return-artifact" v-model="returnArtifact"><option>Gherkin</option><option>SD</option><option value="spec">測試基線</option><option>產品程式</option></select><button data-testid="return-stage" class="button full" :disabled="!!busy" @click="returnStage">退回指定產物</button></div></section></aside></div>
        </template>
        <template v-else-if="view==='db'"><div class="page-header"><div><div class="eyebrow">SQLITE / DATABASE</div><h1>資料庫瀏覽器</h1><p>查閱實際 schema、執行 SQL，並直接檢視此次查詢的結果。</p></div><button class="button" @click="openDialog('connection')">＋ 新增連線</button></div><section class="panel"><div class="panel-heading"><h2>DbGate</h2><button data-testid="open-dbgate" class="button" :disabled="!dbConnectionId||!!busy" @click="openDbGate">開啟 DbGate</button></div><BrowserViewer v-if="browserId" :session-id="browserId" :project-id="projectId" :interactive="true" @error="error=$event" /><p v-else class="empty-small">開啟專案 DbGate，查詢畫面可作為 Playwright 資料斷言與截圖證據。</p></section><div class="db-layout"><aside class="panel schema-panel"><div class="panel-heading"><h2>Schema</h2><button data-testid="db-schema-refresh" class="button quiet small" :disabled="!dbConnectionId" @click="action('schema',refreshSchema)">↻</button></div><div class="panel-body"><select v-model="dbConnectionId" aria-label="資料庫連線" @change="action('schema',refreshSchema)"><option value="">選擇連線</option><option v-for="c in connections" :key="c.id" :value="c.id">{{c.environmentLabel??c.environment_label??c.id}}</option></select><pre data-testid="db-schema" class="schema-content">{{schema?pretty(schema):'尚未選擇資料庫連線'}}</pre></div></aside><div class="document-column"><section class="panel"><div class="panel-heading"><div><span class="eyebrow">QUERY EDITOR</span><h2>SQL 編輯器</h2></div><span data-testid="sql-execution-state" class="tag" aria-live="polite">{{sqlState}}</span></div><div class="panel-body"><textarea data-testid="sql-editor" v-model="sql" class="code-editor sql-editor" aria-label="SQL" spellcheck="false"></textarea><details><summary>繫結參數（JSON array）</summary><textarea v-model="sqlParams" class="code-editor short-editor" aria-label="SQL 參數"></textarea></details><div class="document-actions"><button data-testid="sql-run" class="button primary" :disabled="!dbConnectionId||!!busy" @click="runSql">▷ 執行 SQL</button><span class="muted small-text">結果只來自本次 HTTP 回應</span></div></div></section><section class="panel"><div class="panel-heading"><h2>執行結果</h2><span class="muted">{{dbResult?.rows?.length??0}} 列</span></div><div data-testid="db-results" class="table-scroll"><table v-if="dbResult"><thead><tr><th v-for="column in dbResult.columns" :key="column">{{column}}</th></tr></thead><tbody><tr v-for="(row,i) in dbResult.rows" :key="i"><td v-for="column in dbResult.columns" :key="column">{{row[column]===null?'NULL':pretty(row[column])}}</td></tr></tbody></table><p class="empty-small" v-if="!dbResult">尚未執行查詢</p><p class="query-summary" v-else>changes: {{dbResult.changes??0}}</p></div></section></div></div></template>
        <template v-else-if="view==='browser'"><div class="page-header"><div><div class="eyebrow">MANAGED BROWSER / RECORDING</div><h1>瀏覽器與錄製</h1><p>操作同一個 Playwright session，明確加入斷言，再保存可檢查的腳本。</p></div><button v-if="!browserId" class="button primary" :disabled="!!busy" @click="createBrowser">開啟瀏覽器會話</button><button v-else class="button" :disabled="!!busy" @click="closeBrowser">關閉會話</button></div><div class="browser-layout"><section class="panel"><form class="browser-navigation" @submit.prevent="browserViewer?.navigate(browserUrl)"><span>↗</span><input data-testid="browser-url" v-model="browserUrl" type="url" aria-label="瀏覽器網址" placeholder="https://…"><button class="button small" :disabled="!browserId">前往</button></form><BrowserViewer ref="browserViewer" :project-id="projectId" :session-id="browserId" interactive @event="($event.type==='browser.pageChanged'&&$event.payload?.url)&&(browserUrl=$event.payload.url)" @error="error=$event"/></section><section class="panel"><div class="panel-heading"><div><span class="eyebrow">SEMANTIC RECORDER</span><h2>語意錄製</h2></div><span data-testid="recording-state" class="tag" :class="{recording:recordingState==='recording'}">{{recordingState}}</span></div><div class="panel-body"><div class="button-row"><button data-testid="record-start" class="button primary" :disabled="!browserId||recordingState==='recording'||!!busy" @click="record('start')">● 開始錄製</button><button data-testid="record-stop" class="button" :disabled="recordingState!=='recording'||!!busy" @click="record('stop')">■ 停止錄製</button></div><p class="helper-text">操作真實畫面可錄製導航、點擊與輸入；預期結果需明確加入。</p><hr><div class="field"><label>定位器</label><input data-testid="record-locator" v-model="recordLocator" placeholder="testId=document-content 或 CSS selector"></div><div class="field"><label>斷言種類</label><select data-testid="record-assertion-type" v-model="assertionType"><option value="value">輸入值相等</option><option value="text">文字包含</option><option value="visible">元素可見</option></select></div><div class="field"><label>預期結果</label><input data-testid="record-expected" v-model="recordExpected" placeholder="明確的預期值"></div><button data-testid="record-add-assertion" class="button full" :disabled="recordingState!=='recording'||!recordLocator||!!busy" @click="addAssertion">＋ 加入斷言</button></div></section></div><section class="panel script-panel"><div class="panel-heading"><h2>Playwright TypeScript 草稿</h2><span data-testid="recording-purpose" class="tag">recording</span></div><div class="panel-body"><textarea data-testid="recording-script" v-model="recordingScript" class="code-editor" aria-label="錄製腳本" spellcheck="false"></textarea><div class="field"><label for="recording-secret-bindings">秘密參照綁定（JSON）</label><textarea id="recording-secret-bindings" v-model="recordingSecretBindings" class="code-editor short-editor" aria-label="錄製秘密參照綁定" spellcheck="false" placeholder='[{"alias":"WB_SECRET_...","secretRef":"trusted-registry-id"}]'></textarea><small>alias 填寫錄製別名；secretRef 只填管理員提供的可信註冊表 ID，不可填密碼、token、任意環境變數名稱或其他秘密值。</small><p v-if="requiredSecretAliases.length" class="muted small-text">腳本所需別名：{{requiredSecretAliases.join(', ')}}</p><p v-if="secretBindingError" class="error-text">{{secretBindingError}}</p><p v-if="missingSecretAliases.length" class="notice">尚缺參照：{{missingSecretAliases.join(', ')}}。可先保存未綁定的腳本；重播時缺少綁定或可信解析器會拒絕執行。</p><button v-if="missingSecretAliases.length&&!secretBindingError" type="button" class="button small" @click="addRequiredSecretAliases">加入所需別名，參照由人類填寫</button><small>重播使用已保存版本的綁定。調整後請先另存新版本；瀏覽器不傳送秘密值。</small></div><div class="document-actions"><button class="button primary" :disabled="recordingState!=='stopped'||!recordingScript||!!busy" @click="saveRecording">另存到 SQLite</button><span class="muted small-text">{{recordingActions.length}} 個動作 · 保存不代表測試通過</span></div></div></section></template>
        <template v-else-if="view==='recordings'||view==='integrations'"><div class="page-header"><div><div class="eyebrow">SQLITE / INDEPENDENT SCRIPTS</div><h1>{{recording?recording.fileName??'已保存腳本':view==='integrations'?'使用者整合測試':'錄製腳本'}}</h1><p>DB 定義為權威來源；指定保存版本才可重播，不自動寫入 target Git。</p></div><div v-if="!recording" class="button-row"><button v-if="view==='integrations'" class="button primary" @click="openDialog('integration')">＋ 新增整合測試</button></div></div><section v-if="recording" class="panel"><div class="panel-heading"><h2>腳本原文</h2><span data-testid="script-purpose" class="tag">{{recording.purpose}}</span></div><div class="panel-body"><div class="hash-line"><span>VERSION</span><code>{{recording.versionId??recording.head?.versionId}} / {{recording.rawSha256??recording.head?.rawSha256}}</code></div><textarea data-testid="recording-script" v-model="recordingScript" class="code-editor" aria-label="已保存腳本" spellcheck="false"></textarea><div class="field"><label>重播目標網址</label><input v-model="browserUrl" type="url" placeholder="https://…"></div><div class="field"><label for="recording-secret-bindings">秘密參照綁定（JSON）</label><textarea id="recording-secret-bindings" v-model="recordingSecretBindings" class="code-editor short-editor" aria-label="錄製秘密參照綁定" spellcheck="false" placeholder='[{"alias":"WB_SECRET_...","secretRef":"trusted-registry-id"}]'></textarea><small>alias 填寫錄製別名；secretRef 只填管理員提供的可信註冊表 ID，不可填密碼、token、任意環境變數名稱或其他秘密值。</small><p v-if="requiredSecretAliases.length" class="muted small-text">腳本所需別名：{{requiredSecretAliases.join(', ')}}</p><p v-if="secretBindingError" class="error-text">{{secretBindingError}}</p><p v-if="missingSecretAliases.length" class="notice">尚缺參照：{{missingSecretAliases.join(', ')}}。可先保存未綁定的腳本；重播時缺少綁定或可信解析器會拒絕執行。</p><button v-if="missingSecretAliases.length&&!secretBindingError" type="button" class="button small" @click="addRequiredSecretAliases">加入所需別名，參照由人類填寫</button><small>重播使用已保存版本的綁定。調整後請先另存新版本；瀏覽器不傳送秘密值。</small></div><div class="document-actions"><button class="button" :disabled="!!busy" @click="saveRecordingRevision">另存新版本</button><button class="button primary" :disabled="!!busy" @click="replay">▷ 重播已保存版本</button></div></div></section><section v-if="recording" class="panel script-panel"><div class="panel-heading"><h2>腳本執行畫面</h2><span class="tag">{{report?.status??'NOT_RUN'}}</span></div><BrowserViewer ref="runViewer" :project-id="projectId" :run-id="activeRun" @error="error=$event"/></section><section v-else class="panel"><div class="requirement-list"><a v-for="r in recordings.filter(r=>view==='integrations'?r.purpose==='integration':r.purpose==='recording')" :key="r.id" :href="`/projects/${projectId}/recordings/${r.id}`" @click.prevent="navigate(`/projects/${projectId}/recordings/${r.id}`)"><span class="document-symbol">▷</span><div><strong>{{r.fileName??r.title??r.id}}</strong><p class="mono">{{short(r.versionId)}} · {{r.purpose}}</p></div><span class="tag">{{r.status??'NOT_RUN'}}</span><span class="arrow-link">→</span></a></div><div v-if="!recordings.filter(r=>view==='integrations'?r.purpose==='integration':r.purpose==='recording').length" class="empty-small">尚無已保存的{{view==='integrations'?'整合測試':'錄製腳本'}}。</div></section></template>
        <template v-else-if="view==='runs'"><div class="page-header"><div><div class="eyebrow">EXECUTION REPORT</div><h1>執行報告</h1><p class="mono">{{activeRun}}</p></div></div><section class="panel"><BrowserViewer ref="runViewer" :project-id="projectId" :run-id="activeRun" @error="error=$event"/></section></template>
        <section v-if="report&&(!requirementId||visibleWorkflowStage==='VERIFICATION')" class="panel report-panel"><div class="panel-heading"><div><span class="eyebrow">EXECUTION EVIDENCE</span><h2>本次執行報告</h2></div><span class="tag" :class="{ready:report.status==='PASSED',failed:report.status==='FAILED'}">{{report.status}}</span></div><div class="panel-body"><div class="report-summary"><div><span>範圍</span><strong>{{report.scope}}</strong></div><div><span>全案覆蓋</span><strong>{{report.coverageComplete?'完整':'未完整'}}</strong></div><div><span>已執行 / 必要測試</span><strong>{{report.executedTestKeys?.length??0}} / {{report.requiredTestCount??'—'}}</strong></div></div><p v-if="!report.coverageComplete" class="notice">本次結果不代表未執行案例已通過。未執行：{{report.unexecutedTestKeys?.join(', ')||'請檢查必要測試與執行證據'}}</p><p v-if="report.error" class="error-text">{{report.error}}</p><details v-for="c in report.cases" :key="c.testKey" class="case-evidence"><summary><span class="mono">{{c.testKey}}</span><span class="tag" :class="{failed:c.status==='FAILED'}">{{c.status}}</span><span class="muted">{{c.scenarioId}} / {{c.caseId}}</span></summary><div v-for="s in c.steps" :key="s.actionIndex" class="step-evidence"><div><strong>{{s.actionIndex}} · {{s.status}}</strong><span class="mono">{{s.sourceStepId}}</span></div><p v-if="s.assertion">預期：<code>{{pretty(s.expected)}}</code></p><p>實際：<code>{{pretty(s.actual)}}</code></p><p v-if="s.error??s.mismatch" class="error-text">{{s.error??s.mismatch}}</p><div class="screenshot-list"><a v-for="shot in s.screenshots" :key="shot.id" :href="`/screenshots/${shot.id}`" target="_blank" rel="noopener"><img :src="`/screenshots/${shot.id}`" :alt="`${c.testKey} 第 ${s.actionIndex} 步 ${shot.moment}`" loading="lazy"><span>{{shot.moment}} · {{short(shot.sha256)}}</span></a></div></div></details><details class="report-raw"><summary>完整識別鏈與原始結果</summary><pre>{{pretty(report)}}</pre></details></div></section>
        <div v-if="view==='requirements'&&requirement&&restartableStage(visibleWorkflowStage)" class="workflow-restart-dock"><button type="button" class="button primary workflow-restart-button" data-testid="restart-workflow-stage" :aria-label="'重啟'+workspaceStageLabels[visibleWorkflowStage]+'階段與後續階段'" :title="'重啟'+workspaceStageLabels[visibleWorkflowStage]+'階段與後續階段'" :disabled="!!busy" @click="restartWorkflowStage"><span aria-hidden="true">↻</span>重啟階段</button></div>
      </main>
    </div>
    <dialog ref="dialog" @click="($event.target===dialog)&&dialog?.close()"><form @submit.prevent="dialogKind==='project'?createProject():dialogKind==='requirement'?createRequirement():dialogKind==='feature'?createFeature():dialogKind==='connection'?createConnection():dialogKind==='integration'?createIntegration():dialogKind==='browser-recording-name'?saveBrowserRecording():saveCandidate()"><div class="dialog-heading"><h2>{{dialogKind==='project'?'綁定本機專案':dialogKind==='requirement'?'新增需求':dialogKind==='feature'?'新增 Gherkin':dialogKind==='connection'?'新增 SQLite 連線':dialogKind==='integration'?'新增獨立整合測試':dialogKind==='browser-recording-name'?'保存瀏覽器錄製':'提交產物保存候選'}}</h2><button type="button" class="icon-button" aria-label="關閉對話" @click="dialog?.close()">×</button></div><div class="dialog-body"><template v-if="dialogKind==='browser-recording-name'"><div class="field"><label for="browser-recording-name">名稱</label><input id="browser-recording-name" v-model="browserRecordingName" required maxlength="160" autofocus placeholder="例如：登入流程"></div></template><template v-else-if="dialogKind==='project'"><div class="field"><label for="project-name">工作區名稱</label><input id="project-name" v-model="newProject.name" required maxlength="160" autofocus placeholder="例如：訂單工作區"></div><div class="field"><label for="workspace-ref">本機程式碼目錄</label><input id="workspace-ref" v-model="newProject.workspaceRef" required placeholder="/absolute/path/to/project"><small>填寫已存在的專案絕對路徑；程式與 terminal 使用這個目錄。</small></div></template><div v-else-if="dialogKind==='requirement'"><div class="field"><label for="requirement-key">需求編號</label><input id="requirement-key" v-model="newRequirement" required placeholder="REQ-001"></div><fieldset class="requirement-workspace-picker"><legend>綁定工作區</legend><label v-for="p in projects" :key="p.id"><input type="checkbox" v-model="newRequirementProjectIds" :value="p.id"><span>{{p.name}}<small class="mono">{{p.workspaceRef}}</small></span></label><p v-if="!projects.length" class="muted">請先回需求首頁下方新增工作區。</p></fieldset></div><div v-else-if="dialogKind==='feature'" class="field"><label for="feature-key">Gherkin 名稱（不含副檔名）</label><input id="feature-key" v-model="newFeature" required placeholder="例如：checkout"><small>各自管理 .feature、.sd.md、.feature.spec.ts 與確認狀態。</small></div><template v-else-if="dialogKind==='connection'"><div class="field"><label>SQLite 檔案路徑</label><input v-model="newConnection.sqliteFileRef" required placeholder="/workspace/project/data.sqlite"></div><div class="field"><label>環境名稱</label><input v-model="newConnection.environmentLabel" required></div><div class="field"><label>對應網站 URL（選填）</label><input v-model="newConnection.appBaseUrl" type="url"></div><div class="field"><label>DbGate URL（選填）</label><input v-model="newConnection.dbgateUrl" type="url"><small>需連接上方指定的 SQLite 檔案。</small></div><div class="field"><label>DbGate 連線名稱（選填）</label><input v-model="newConnection.dbgateConnectionName"></div></template><template v-else-if="dialogKind==='integration'"><div class="field"><label>檔案名稱</label><input v-model="integrationFileName" required></div><div class="field"><label>目標 URL</label><input v-model="integrationTargetUrl" type="url" placeholder="https://…"></div><div class="field"><label>Playwright TypeScript 原文</label><textarea v-model="integrationDraft" required class="code-editor" spellcheck="false" placeholder="貼上實際的整合測試程式。保存只檢查原文，不代表已執行。"></textarea></div></template><template v-else><p class="muted small-text">候選不會解除編輯鎖。伺服器仍依階段與原文檢核決定是否保存。</p><div class="field"><label>產物</label><select data-testid="artifact-save-kind" v-model="candidateKind"><option value="gherkin">Gherkin</option><option value="sd">SD</option><option value="spec">spec.ts</option></select></div><textarea data-testid="artifact-save-candidate" v-model="candidateText" class="code-editor short-editor" aria-label="保存候選原文"></textarea><p v-if="candidateError" data-testid="artifact-save-error" class="error-text">{{candidateError}}</p></template><p v-if="error" class="error-text">{{error}}</p><div class="dialog-buttons"><button type="button" class="button" @click="dialog?.close()">取消</button><button :data-testid="dialogKind==='candidate'?'artifact-save-attempt':undefined" class="button primary" :disabled="!!busy||(dialogKind==='requirement'&&newRequirementProjectIds.length===0)">{{dialogKind==='browser-recording-name'?'保存':dialogKind==='candidate'?'嘗試保存':'建立'}}</button></div></div></form></dialog>
    <div v-if="notification&&view!=='terminal'&&view!=='browser-recorder'" class="toast" role="status">✓ {{notification}}</div>
  </div>
</template>
